<template>
  <section ref="entryRoot" class="ai-entry" aria-label="快捷录入工作台">
    <div class="ai-entry-heading"><strong>快捷录入</strong><button type="button" @click="$emit('close')">返回对话</button></div>
    <p class="ai-entry-scope">{{ ownerLabel }} · {{ date }}<template v-if="selectedEntry"> · {{ selectedEntry.levels.join(' / ') }} · {{ selectedOperation?.label }}</template></p>
    <p v-if="error" role="alert" class="ai-entry-error">{{ error }}</p>
    <p v-if="loading">正在核对当前账号的菜单、字段和访问授权…</p>
    <p v-else-if="!options.length">没有可用的快捷录入菜单。子账号需独立授权；后台请先选择数据账号。</p>
    <template v-else>
      <div v-if="recentEntries.length" class="ai-entry-recents"><small>常用入口</small><button v-for="recent in recentEntries" :key="`${recent.key}:${recent.action}`" type="button" :disabled="busy || externalBusy" @click="useRecent(recent.key,recent.action)">{{ recent.label }}</button></div>
      <div class="ai-entry-menu-grid">
        <label v-for="depth in visibleDepth" :key="depth">{{ levelLabels[depth-1] }}<select :value="selections[depth-1] || ''" :aria-label="levelLabels[depth-1]" :disabled="busy || externalBusy || (depth>1&&!selections[depth-2])" @change="selectLevel(depth-1,($event.target as HTMLSelectElement).value)"><option value="">请选择{{ levelLabels[depth-1] }}</option><option v-for="label in levelChoices(depth-1)" :key="label" :value="label">{{ label }}</option></select></label>
        <label v-if="leafOptions.length>1">录入事项<select v-model="entryKey" aria-label="录入事项" :disabled="busy || externalBusy"><option value="">请选择具体录入事项</option><option v-for="entry in leafOptions" :key="entry.key" :value="entry.key">{{ entry.label }}</option></select></label>
        <label v-if="selectedEntry">操作类型<select v-model="action" aria-label="操作类型" :disabled="busy || externalBusy"><option value="">请选择操作</option><option v-for="operation in selectedEntry.operations" :key="operation.action" :value="operation.action">{{ operation.label }}</option></select></label>
        <label>录入日期<input v-model="date" type="date" aria-label="快捷录入日期" :disabled="busy || externalBusy" /></label>
      </div>
      <p v-if="!locked" class="ai-entry-hint">先选择并确认录入位置，再发送文字或照片。只显示当前有权限、已支持写入的菜单；选择菜单不会增加权限。</p>
      <el-button v-if="!locked" type="primary" :disabled="busy || externalBusy || !selectedOperation" @click="lockScope">确认录入位置</el-button>
      <template v-else>
        <p class="ai-entry-locked" role="status">位置已锁定。可在下方发送文字或照片让助手识别，也可直接填写核对表；只补充缺失信息。</p>
        <p v-if="selectedEntry?.note" class="ai-entry-hint">{{ selectedEntry.note }}</p>
        <template v-if="isRegistration">
          <p class="ai-entry-hint">序号是主表左侧的001，不是客户编号。每批最多5条；先生成草稿，再核对确认。</p>
          <label class="ai-entry-text">短句或批量粘贴<textarea v-model="compact" :disabled="busy || externalBusy" rows="2" placeholder="001 小张 60 月结款&#10;002 小李 80 未结款" aria-label="快捷录入短句" /></label>
          <button type="button" :disabled="busy || externalBusy || !compact.trim()" @click="parse">填入核对表</button>
          <div class="ai-entry-defaults"><label><input v-model="reuseCustomer" type="checkbox" />本次会话沿用客户</label><label><input v-model="reuseStatus" type="checkbox" />沿用费用状态</label><small>金额不自动沿用；切换账号、菜单或日期会清空。</small></div>
          <article v-for="(row,index) in rows" :key="index" class="ai-entry-row">
            <div class="ai-entry-row-heading"><strong>第 {{ index+1 }} 条</strong><button v-if="rows.length>1" type="button" :disabled="busy || externalBusy" @click="rows.splice(index,1)">移除</button></div>
            <label>样品序号<input v-model="row.sequence" :disabled="busy || externalBusy" :aria-label="`第${index+1}条样品序号`" /></label>
            <label>付款客户<el-autocomplete :model-value="row.customerName" :fetch-suggestions="fetchCustomers" :disabled="busy || externalBusy" :trigger-on-focus="false" :aria-label="`第${index+1}条付款客户`" placeholder="输入姓名匹配本账号客户" @update:model-value="(value:string)=>changeName(row,value)" @select="(item:Record<string,any>)=>selectCustomer(row,item)" /></label>
            <label class="ai-entry-new-customer"><input v-model="row.createCustomer" type="checkbox" :disabled="busy || externalBusy" />找不到时新建同名客户（确认后才创建，需客户新增权限）</label>
            <label>样品金额（元）<el-input-number v-model="row.price" :disabled="busy || externalBusy" :min="0" :max="9999999999.99" :precision="2" :aria-label="`第${index+1}条样品金额`" /></label>
            <label>费用状态<select v-model="row.paymentStatus" :disabled="busy || externalBusy" :aria-label="`第${index+1}条费用状态`"><option value="">请选择</option><option v-for="status in statuses" :key="status" :value="status">{{ status }}</option></select></label>
          </article>
          <p class="ai-entry-hint">预存款涉及会员和台账，请使用原页面；这里不会直接扣款或冲正。</p>
          <div class="ai-entry-actions"><button type="button" :disabled="busy || externalBusy || rows.length>=5" @click="addRow">增加一条</button><el-button type="primary" :loading="busy" :disabled="!canPrepare" @click="prepare">生成待确认草稿</el-button></div>
        </template>
        <template v-else>
          <label v-if="selectedOperation?.requiresId" class="ai-entry-target">选择既有记录<select v-model="targetId" aria-label="快捷录入既有记录" :disabled="busy || externalBusy"><option value="">请选择要修改或处理的记录</option><option v-for="record in targetRecords" :key="String(record.id)" :value="String(record.id)">{{ entryRecordLabel(record) }}</option></select><small>仅当前账号的授权记录，最多50条。</small><input v-model="targetKeyword" placeholder="按可见名称或序号筛选" aria-label="录入记录筛选" /><button type="button" :disabled="busy || externalBusy" @click="loadRecords">查找记录</button></label>
          <div class="ai-entry-form">
            <AiEntryField v-for="key in activeFields" :key="key" :field-key="key" :label="fieldLabel(key)" :schema="selectedOperation?.input.properties?.[key] || {}" :model-value="data[key]" :required="selectedOperation?.input.required?.includes(key)" :disabled="busy || externalBusy || fixedDateFields.includes(key)" :references="references[key]" @update:model-value="data[key]=$event" />
          </div>
          <label v-if="optionalFields.length" class="ai-entry-optional">添加可选字段<select value="" aria-label="添加录入字段" :disabled="busy || externalBusy" @change="addField(($event.target as HTMLSelectElement).value)"><option value="">请选择需要填写的字段</option><option v-for="key in optionalFields" :key="key" :value="key">{{ fieldLabel(key) }}</option></select></label>
          <p v-if="!activeFields.length" class="ai-entry-hint">该操作不需要填写额外字段，请先选择并核对既有记录。</p>
          <el-button type="primary" :loading="busy" :disabled="!canPrepare" @click="prepare">生成待确认草稿</el-button>
        </template>
      </template>
    </template>
  </section>
</template>
<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {aiClient,currentAiGrants} from './client'
import {nextSequence,parseEntryRows,todayInBeijing,entryRecordLabel,entryReferenceResources,type EntryOption,type EntryRow,type EntryPageContext,type EntryContext,type EntryInputSchema} from './entry'
import {demoEntryOptions} from './entry-options'
import AiEntryField from './AiEntryField.vue'
import type {AiChatResponse,AiProposal} from './types'
const props=defineProps<{audience:'frontend'|'admin';actorId:string;ownerId:string;ownerLabel:string;modelId:string;conversationId:string;enabled:boolean;externalBusy?:boolean;apiBase?:string;mockMode?:boolean;pageContext?:EntryPageContext;initialContext?:EntryContext}>()
const emit=defineEmits<{close:[];context:[EntryContext|undefined];'scope-change':[];proposed:[AiChatResponse];activity:[boolean]}>()
const request=aiClient(props.audience,props.apiBase),entryRoot=ref<HTMLElement>()
const options=ref<EntryOption[]>([]),selections=ref<string[]>([]),entryKey=ref(''),action=ref(''),locked=ref(false),date=ref(props.initialContext?.date||props.pageContext?.date||todayInBeijing())
const compact=ref(''),error=ref(''),loading=ref(false),busy=ref(false),reuseCustomer=ref(false),reuseStatus=ref(false),last=ref<EntryRow>(),rows=ref<EntryRow[]>([blank(props.pageContext?.sequence||'')])
const data=ref<Record<string,unknown>>({}),activeFields=ref<string[]>([]),targetId=ref(''),targetKeyword=ref(''),targetRecords=ref<Record<string,unknown>[]>([]),references=ref<Record<string,Record<string,unknown>[]>>({})
const recentTargets=ref<{key:string;action:string}[]>([])
const recentEntries=computed(()=>recentTargets.value.flatMap(target=>{const entry=options.value.find(entry=>entry.key===target.key),operation=entry?.operations.find(operation=>operation.action===target.action);return entry&&operation?[{...target,label:`${entry.levels.join(' / ')} · ${operation.label}`}]:[]}))
const levelLabels=['一级菜单','二级菜单','三级菜单'],fixedDateFields=['date','paymentDate','occurredOn','rechargeDate','startDate','month'],statuses=['已结款','未结款','月结款']
let generation=0,initializing=false
const leafOptions=computed(()=>options.value.filter(entry=>entry.levels.length===selections.value.filter(Boolean).length&&entry.levels.every((label,index)=>selections.value[index]===label)))
const selectedEntry=computed(()=>leafOptions.value.find(entry=>entry.key===entryKey.value))
const selectedOperation=computed(()=>selectedEntry.value?.operations.find(operation=>operation.action===action.value))
const isRegistration=computed(()=>entryKey.value==='samples'&&action.value==='prepare_sample_registration')
const visibleDepth=computed(()=>{if(!selections.value[0])return 1;return Math.max(1,...options.value.filter(entry=>entry.levels[0]===selections.value[0]).map(entry=>entry.levels.length))})
const optionalFields=computed(()=>Object.keys(selectedOperation.value?.input.properties||{}).filter(key=>!activeFields.value.includes(key)))
const currentScope=computed<EntryContext|undefined>(()=>selectedOperation.value?{scene:selectedEntry.value!.key,action:action.value,date:date.value,...(isRegistration.value?{sequence:rows.value[0]?.sequence}:{} )}:undefined)
const canPrepare=computed(()=>props.enabled&&props.modelId&&!busy.value&&!props.externalBusy&&locked.value&&(isRegistration.value?rows.value.length>0&&rows.value.every(row=>row.sequence.trim()&&row.customerName.trim()&&row.price!==null&&Number.isFinite(row.price)&&statuses.includes(row.paymentStatus)):Boolean(selectedOperation.value)&&(!selectedOperation.value?.requiresId||targetId.value)&&validInput(selectedOperation.value!.input,data.value)&&(!['update','save','prepare_sample_change'].includes(action.value)||Object.entries(data.value).some(([key,value])=>value!==undefined&&!fixedDateFields.includes(key)&&key!=='rowKind'))))
function blank(sequence=''):EntryRow{return {sequence,customerName:'',createCustomer:false,price:null,paymentStatus:''}}
function levelChoices(index:number){return [...new Set(options.value.filter(entry=>selections.value.slice(0,index).every((label,i)=>label&&entry.levels[i]===label)).map(entry=>entry.levels[index]).filter(Boolean))]}
function resetValues(){compact.value='';rows.value=[blank(props.pageContext?.sequence||'')];last.value=undefined;reuseCustomer.value=false;reuseStatus.value=false;data.value={};activeFields.value=[];targetId.value='';targetKeyword.value='';targetRecords.value=[];references.value={};error.value=''}
function unlock(){generation++;if(locked.value&&!initializing)emit('scope-change');locked.value=false;emit('context',undefined);resetValues()}
function defaultAction(entry:EntryOption|undefined){const ops=entry?.operations||[];return entry?.key==='samples'&&ops.some(operation=>operation.action==='prepare_sample_registration')?'prepare_sample_registration':ops.length===1?ops[0].action:''}
function syncLeaf(){const leaf=leafOptions.value,primary=leaf.find(entry=>entry.label===entry.levels.at(-1));if(leaf.length===1||primary)entryKey.value=(primary||leaf[0]).key;else if(!leaf.some(entry=>entry.key===entryKey.value))entryKey.value='';action.value=defaultAction(selectedEntry.value)}
function selectLevel(index:number,value:string){if(props.externalBusy)return;unlock();selections.value=[...selections.value.slice(0,index),value];syncLeaf()}
function initializeEntry(entry:EntryOption,selectedAction?:string){selections.value=[...entry.levels];entryKey.value=entry.key;action.value=selectedAction||defaultAction(entry)}
async function loadOptions(){const token=++generation;loading.value=false;options.value=[];locked.value=false;emit('context',undefined);if(!props.enabled||props.audience==='admin'&&!props.ownerId&&!props.mockMode)return;loading.value=true;try{const result=props.mockMode?{scenes:demoEntryOptions(props.audience)}:await request<{scenes:EntryOption[]}>('/ai/entry/options',{method:'POST',body:{ownerId:props.ownerId||undefined,grants:currentAiGrants(props.audience)}});if(token!==generation)return;options.value=result.scenes;initializing=true;const initial=props.initialContext&&options.value.find(entry=>entry.key===props.initialContext!.scene);const page=options.value.find(entry=>entry.path===props.pageContext?.menu);if(initial){initializeEntry(initial,props.initialContext?.action);date.value=props.initialContext!.date;locked.value=Boolean(selectedOperation.value);initFields();emit('context',locked.value?currentScope.value:undefined);if(locked.value)void loadRecords()}else if(page)initializeEntry(page);else if(options.value.length===1)initializeEntry(options.value[0]);initializing=false}catch(e){if(token===generation)error.value=(e as Error).message}finally{if(token===generation)loading.value=false}}
function initFields(){const input=selectedOperation.value?.input;activeFields.value=[...(input?.required||[])];data.value={};for(const key of activeFields.value){const schema=input?.properties?.[key];if(fixedDateFields.includes(key))data.value[key]=key==='month'?date.value.slice(0,7):date.value;else if(schema?.const!==undefined)data.value[key]=schema.const;else if(schema?.type==='array')data.value[key]=Array.from({length:schema.minItems||0},()=>schema.items?.properties?{}:'')}}
function recentKey(){return `ys-ai-entry-recents:${props.audience}:${props.actorId}`}
function loadRecents(){try{const parsed=JSON.parse(localStorage.getItem(recentKey())||'[]');recentTargets.value=Array.isArray(parsed)?parsed.filter(target=>typeof target?.key==='string'&&typeof target?.action==='string').slice(0,5):[]}catch{recentTargets.value=[]}}
function rememberTarget(){if(!currentScope.value)return;const target={key:currentScope.value.scene,action:currentScope.value.action!};recentTargets.value=[target,...recentTargets.value.filter(item=>item.key!==target.key||item.action!==target.action)].slice(0,5);try{localStorage.setItem(recentKey(),JSON.stringify(recentTargets.value))}catch{}}
function useRecent(key:string,selectedAction:string){if(props.externalBusy)return;const entry=options.value.find(entry=>entry.key===key);if(!entry)return;unlock();initializing=true;initializeEntry(entry,selectedAction);initializing=false}
async function lockScope(){if(!currentScope.value||props.externalBusy)return;emit('scope-change');locked.value=true;initFields();rememberTarget();emit('context',currentScope.value);await loadRecords()}
function fieldLabel(key:string){return selectedEntry.value?.writeFields.find(field=>field.key===key||field.key===`inputs.${key}`)?.label||({rowKind:'行类型',reason:'原因',month:'月份',customer:'客户名称'} as Record<string,string>)[key]||key}
function addField(key:string){if(!key||activeFields.value.includes(key))return;activeFields.value.push(key);if(fixedDateFields.includes(key))data.value[key]=key==='month'?date.value.slice(0,7):date.value;void loadRecords()}
function validInput(schema:EntryInputSchema,value:unknown):boolean {const definition=schema.anyOf?.find(item=>item.type!=='null')||schema;if(definition.properties){const object=value as Record<string,unknown>|undefined;return Boolean(object)&& (definition.required||[]).every(key=>object![key]!==undefined&&object![key]!==null&&object![key]!==''&&validInput(definition.properties![key],object![key]))}if(definition.type==='array')return Array.isArray(value)&&value.length>=(definition.minItems||0)&&value.every(item=>validInput(definition.items||{},item));if(definition.type==='number'||definition.type==='integer')return typeof value==='number'&&Number.isFinite(value);if(definition.type==='boolean')return typeof value==='boolean';return value!==undefined&&value!==null}
async function loadRecords(){if(!locked.value||!currentScope.value||props.mockMode)return;const token=generation,scope={...currentScope.value},operation=selectedOperation.value!;const resources=[...new Set(Object.keys(operation.input.properties||{}).map(key=>entryReferenceResources[key]).filter(Boolean))];try{if(operation.requiresId){const result=await request<{rows:Record<string,unknown>[]}>('/ai/entry/records',{method:'POST',body:{ownerId:props.ownerId||undefined,entryContext:scope,resource:scope.scene,keyword:targetKeyword.value,grants:currentAiGrants(props.audience)}});if(token===generation)targetRecords.value=result.rows}for(const resource of resources){const result=await request<{rows:Record<string,unknown>[]}>('/ai/entry/records',{method:'POST',body:{ownerId:props.ownerId||undefined,entryContext:scope,resource,grants:currentAiGrants(props.audience)}});if(token===generation)for(const [key,mapped]of Object.entries(entryReferenceResources))if(mapped===resource)references.value[key]=result.rows}}catch(e){if(token===generation)error.value=(e as Error).message}}
function parse(){try{rows.value=parseEntryRows(compact.value,{customerName:reuseCustomer.value?last.value?.customerName:undefined,paymentStatus:reuseStatus.value?last.value?.paymentStatus:undefined});error.value=''}catch(e){error.value=(e as Error).message}}
function addRow(){const previous=rows.value.at(-1),row=blank(nextSequence(previous?.sequence||''));if(reuseCustomer.value&&previous){row.customerName=previous.customerName;row.customerId=previous.customerId}if(reuseStatus.value)row.paymentStatus=previous?.paymentStatus||'';rows.value.push(row)}
function changeName(row:EntryRow,name:string){row.customerName=name;row.customerId=undefined;row.createCustomer=false}
function selectCustomer(row:EntryRow,item:Record<string,any>){row.customerName=item.value;row.customerId=item.id;row.createCustomer=false}
async function fetchCustomers(keyword:string,callback:(items:Record<string,any>[])=>void){const token=generation;if(props.mockMode){callback([]);return}try{const found=await request<{id:string;name:string}[]>('/ai/entry/customers',{method:'POST',body:{ownerId:props.ownerId||undefined,keyword,grants:currentAiGrants(props.audience)}});callback(token===generation?found.map(item=>({...item,value:item.name})):[])}catch(e){callback([]);if(token===generation)error.value=(e as Error).message}}
async function prepare(){if(!canPrepare.value||!currentScope.value)return;if(props.mockMode){error.value='演示模式只预览核对表，不生成真实草稿或修改数据。';return}busy.value=true;error.value='';const token=generation,scope={...currentScope.value},snapshot=rows.value.map(row=>({...row,date:date.value}));try{const result=await request<AiChatResponse>('/ai/entry/proposals',{method:'POST',body:{modelId:props.modelId,ownerId:props.ownerId||undefined,conversationId:props.conversationId||undefined,entryContext:scope,grants:currentAiGrants(props.audience),...(isRegistration.value?{rows:snapshot}:{id:targetId.value||undefined,data:data.value})}});if(token!==generation)return;emit('proposed',result);if(isRegistration.value){last.value={...rows.value.at(-1)!};const next=blank(nextSequence(last.value.sequence));if(reuseCustomer.value){next.customerName=last.value.customerName;next.customerId=last.value.customerId}if(reuseStatus.value)next.paymentStatus=last.value.paymentStatus;rows.value=[next];compact.value=''}else{initFields();targetId.value=''}}catch(e){if(token===generation)error.value=(e as Error).message}finally{busy.value=false}}
async function editProposal(proposal:AiProposal){const scope=proposal.preview.entry?.context||(proposal.preview.target?{scene:'samples' as const,action:'prepare_sample_registration',date:proposal.preview.target.date}:undefined);if(!scope)return;const entry=options.value.find(entry=>entry.key===scope.scene);if(!entry)throw new Error('此菜单已不在授权范围内');initializing=true;initializeEntry(entry,scope.action);date.value=scope.date;locked.value=true;initFields();if(proposal.preview.entry){data.value={...proposal.preview.entry.data};activeFields.value=Object.keys(data.value);targetId.value=proposal.preview.entry.id||''}else{const values=Object.fromEntries(proposal.preview.fields.map(field=>[field.key,field.after]));rows.value=[{sequence:proposal.preview.target!.sequence,customerName:String(values.customerText||''),price:typeof values.price==='number'?values.price:null,paymentStatus:String(values.paymentStatus||'') as EntryRow['paymentStatus'],createCustomer:false}]}initializing=false;emit('context',currentScope.value);await loadRecords()}
async function focusNext(){await nextTick();entryRoot.value?.scrollIntoView?.({block:'start',behavior:'smooth'});(entryRoot.value?.querySelector('[aria-label="快捷录入短句"]') as HTMLTextAreaElement|null)?.focus()}
watch(entryKey,()=>{if(initializing)return;if(locked.value)unlock();action.value=defaultAction(selectedEntry.value)},{flush:'sync'})
watch(action,()=>{if(!initializing&&locked.value)unlock()},{flush:'sync'})
watch(date,()=>{if(!initializing)unlock()},{flush:'sync'})
watch(()=>[props.actorId,props.ownerId,props.enabled],()=>{generation++;initializing=true;selections.value=[];entryKey.value='';action.value='';locked.value=false;resetValues();loadRecents();initializing=false;void loadOptions()})
watch(()=>props.pageContext?.date,value=>{if(value&&value!==date.value)date.value=value})
watch(()=>props.pageContext?.sequence,value=>{if(!compact.value&&rows.value.length===1&&!rows.value[0].customerName)rows.value[0].sequence=value||''})
watch(rows,()=>{if(locked.value&&isRegistration.value)emit('context',currentScope.value)},{deep:true})
watch(busy,value=>emit('activity',value));onMounted(()=>{loadRecents();void loadOptions()});onBeforeUnmount(()=>{generation++;emit('activity',false)})
defineExpose({editProposal,focusNext})
